CREATE TABLE IF NOT EXISTS "Vivero" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"latitud" DECIMAL NOT NULL CHECK("latitud" >= -90 AND "latitud" <= 90),
	"longitud" DECIMAL NOT NULL CHECK("longitud" >= -180 AND "longitud" <= 180),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Zona" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"id_vivero" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Producto" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"id_vivero" INTEGER NOT NULL,
	"precio" DECIMAL NOT NULL DEFAULT 0.0 CHECK("precio" >= 0.0),
	"cantidad" INTEGER NOT NULL DEFAULT 0 CHECK("cantidad" >= 0),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "pedido" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"id_producto" INTEGER NOT NULL,
	"id_cliente" INTEGER NOT NULL,
	"cantidad" INTEGER NOT NULL CHECK("cantidad" > 0),
	"fecha_pedido" DATE NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "cliente" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nombre" VARCHAR(50) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Tajinaste_Plus" (
	"id_cliente" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"fecha_alta" DATE NOT NULL,
	"fecha_baja" DATE,
	"bonificacion" DECIMAL NOT NULL DEFAULT 0.0 CHECK(0.0 >= "bonificacion" AND "bonificacion" <= 1.0),
	PRIMARY KEY("id_cliente")
);

CREATE TABLE IF NOT EXISTS "Venta" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"id_pedido" INTEGER NOT NULL,
	"id_cliente" INTEGER NOT NULL,
	"id_empleado" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Tarea" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"id_zona" INTEGER NOT NULL,
	"tipo_tarea" VARCHAR(255),
	"fecha_inicio" DATE NOT NULL,
	"fecha_fin" DATE,
  CHECK ("fecha_fin" IS NULL OR "fecha_fin" >= "fecha_inicio"),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Puesto" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"id_tarea" INTEGER,
	"nombre" VARCHAR(50) NOT NULL,
	"descripcion" VARCHAR(255),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Empleado" (
	"id" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,
	"nombre" VARCHAR(50) NOT NULL,
	"id_puesto" INTEGER,
	PRIMARY KEY("id")
);

ALTER TABLE "Zona"
ADD FOREIGN KEY("id_vivero") REFERENCES "Vivero"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "Tajinaste_Plus"
ADD FOREIGN KEY("id_cliente") REFERENCES "cliente"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "pedido"
ADD FOREIGN KEY("id_cliente") REFERENCES "cliente"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "Venta"
ADD FOREIGN KEY("id_pedido") REFERENCES "pedido"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "Venta"
ADD FOREIGN KEY("id_cliente") REFERENCES "cliente"("id")
ON UPDATE CASCADE ON DELETE RESTRICT;
ALTER TABLE "pedido"
ADD FOREIGN KEY("id_producto") REFERENCES "Producto"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "Producto"
ADD FOREIGN KEY("id_vivero") REFERENCES "Vivero"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "Puesto"
ADD FOREIGN KEY("id_tarea") REFERENCES "Tarea"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "Venta"
ADD FOREIGN KEY("id_empleado") REFERENCES "Empleado"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "Empleado"
ADD FOREIGN KEY("id_puesto") REFERENCES "Puesto"("id")
ON UPDATE NO ACTION ON DELETE SET NULL;
ALTER TABLE "Tarea"
ADD FOREIGN KEY("id_zona") REFERENCES "Zona"("id")
ON UPDATE NO ACTION ON DELETE CASCADE;
